mapper.sql:
WHERE s.status = 'ACTIVE' AND MBRIntersects( ST_SRID( POLYGON(LINESTRING( POINT(#{area.swLng}, #{area.swLat}), POINT(#{area.neLng}, #{area.swLat}), POINT(#{area.neLng}, #{area.neLat}), POINT(#{area.swLng}, #{area.neLat}), POINT(#{area.swLng}, #{area.swLat}))), 4326), s.location) AND ST_Latitude(s.location) BETWEEN #{area.swLat} AND #{area.neLat} AND ST_Longitude(s.location) BETWEEN #{area.swLng} AND #{area.neLng}
AND s.type IN
#{type}
AND (s.type <> 'BAKJI' OR b.has_water = TRUE)
AND (s.type <> 'BAKJI' OR b.has_toilet = TRUE)
AND s.park_warning = FALSE
